import React from 'react';
import {listInstruments,getInstrument} from '../domain/instruments.mjs';

export function regimeFieldEdit(node,section,field,raw){
 const time={periodMinutes:'periodMs',maxAgeMinutes:'maxAgeMs',minimumDwellMinutes:'minimumDwellMs'};if(section==='program'&&time[field]){if(!String(raw).trim())throw Error('시간을 입력하세요.');return regimeFieldEdit(node,section,time[field],String(Number(raw)*60000));}
 const numeric=['periodMs','maxAgeMs','minimumDwellMs','highIntensity','x.center','x.scale','y.center','y.scale','source.lookbackBars'],text=['inputId','x.label','y.label','question'];
 if(!(section==='program'?numeric.includes(field):text.includes(field)||/^items\.\d+\.(id|label|description)$/.test(field)||/^inputs\.\d+$/.test(field)))throw Error('등록된 라우터 설정을 선택하세요.');
 const value=section==='program'?Number(raw):raw;if(section==='program'&&(!String(raw).trim()||!Number.isFinite(value))||section==='programText'&&!String(value).trim())throw Error('설정 값을 입력하세요.');
 const config=structuredClone(node.config),parts=field.split('.');let target=config;for(const key of parts.slice(0,-1))target=target[key];target[parts.at(-1)]=value;return config;
}
export function RegimeNodeControls({data,NumberControl,SelectControl}){
 const n=data.node,c=n.config,patch=config=>data.onPatch(n,{config});
 const text=(field,title,value)=>{const key=n.id+':programText:'+field,long=field==='question'||field.endsWith('.description'),props={className:'nodrag nopan nowheel','aria-label':n.label+' · '+title,value:data.fieldDrafts?.[key]??value??'',title:value,disabled:data.saving,'aria-invalid':data.invalidField===key||undefined,onChange:e=>data.onField?.(key,e.target.value,e.currentTarget),onBlur:()=>data.onCommit?.(n,'programText',field,key)};return <label className={'strategy-inline-field'+(long?' strategy-program-long':'')} key={field}><span>{title}</span>{long?<textarea {...props} rows={3}/>:<input {...props}/>}</label>;};
 const number=(field,title,value)=><NumberControl key={field} data={data} section="program" field={field} title={title} value={value}/>;
 if(n.type==='REGIME_INPUT'){const instruments=listInstruments(),instrument=c.source?getInstrument(c.source.instrumentId):null;if(instrument&&!instruments.some(v=>v.id===instrument.id))instruments.push(instrument);return <>{text('inputId','입력 변수 ID',c.inputId)}<SelectControl data={data} title="자료 출처" value={c.source?'MARKET':'VARIABLE'} onChange={kind=>{const next={...c};if(kind==='MARKET'){next.source={kind:'MARKET',instrumentId:'crypto:okx:BTC-USDT',timeframe:'1h',lookbackBars:30};next.valueType='CONTEXT';}else delete next.source;patch(next);}}><option value="VARIABLE">연결 변수</option><option value="MARKET">확정 시세</option></SelectControl>{c.source?<><SelectControl data={data} title="조회 종목" value={c.source.instrumentId} onChange={instrumentId=>{const instrument=getInstrument(instrumentId);patch({...c,source:{...c.source,instrumentId,timeframe:instrument.timeframes.includes(c.source.timeframe)?c.source.timeframe:instrument.defaultTimeframe}});}}>{instruments.map(v=><option key={v.id} value={v.id}>{v.name+' · '+v.symbol}</option>)}</SelectControl><SelectControl data={data} title="봉 주기" value={c.source.timeframe} onChange={timeframe=>patch({...c,source:{...c.source,timeframe}})}>{instrument.timeframes.map(v=><option key={v} value={v}>{v}</option>)}</SelectControl>{number('source.lookbackBars','확정 봉 개수',c.source.lookbackBars)}</>:<SelectControl data={data} title="자료형" value={c.valueType} onChange={valueType=>patch({...c,valueType})}><option value="NUMBER">숫자</option><option value="CONTEXT">시장 자료</option><option value="TEXT">텍스트</option><option value="OHLCV">확정 시세</option></SelectControl>}</>;}
 if(n.type==='CHOICE_LIST')return <>{c.items.map((v,i)=><fieldset key={i} className="strategy-inline-group"><legend>{v.label||'선택지 '+(i+1)}</legend>{text('items.'+i+'.id','선택지 ID',v.id)}{text('items.'+i+'.label','선택지 이름',v.label)}{text('items.'+i+'.description','판단 기준',v.description)}<button type="button" className="button small nodrag" disabled={data.saving||c.items.length<=2} onClick={()=>patch({...c,items:c.items.filter((_,j)=>j!==i)})}>선택지 삭제</button></fieldset>)}<button type="button" className="button small nodrag" disabled={data.saving||c.items.length>=32} onClick={()=>{let i=c.items.length+1;while(c.items.some(v=>v.id==='choice-'+i))i++;patch({...c,items:[...c.items,{id:'choice-'+i,label:'새 선택지',description:'이 선택지의 판단 기준'}]});}}>선택지 추가</button></>;
 if(n.type==='STRATEGY_REFERENCE')return <SelectControl data={data} title="전략·마인드 묶음 버전" value={c.model?.id??''} onChange={id=>{const m=data.programModels?.find(m=>m.id===id);if(m)data.onPatch(n,{label:m.name,config:{model:{id:m.id,version:m.version??1,contentHash:m.contentHash,...(m.kind==='mind-preset'?{kind:m.kind}:{})}}});}}><option value="">전략 선택</option>{(data.programModels??[]).map(m=><option key={m.id} value={m.id}>{m.name+(m.kind==='mind-preset'?' · 마인드 '+m.minds.length+'개':' · v'+m.version)}</option>)}</SelectControl>;
 if(n.type==='REGIME_ROUTER')return <>{number('minimumDwellMinutes','최소 유지 시간 · 분',c.minimumDwellMs/60000)}<p className="strategy-inline-caption">기존 전략이 자기 보유·미확정 주문을 정리한 뒤 다음 전략에 인계합니다.</p></>;
 if(n.type==='REGIME_CLASSIFIER'&&c.kind==='FIXED')return <p className="strategy-inline-caption">연결한 묶음의 모든 마인드를 저장된 배분으로 실행합니다.</p>;
 if(n.type==='REGIME_CLASSIFIER')return <>{number('periodMinutes','재판단 주기 · 분',c.periodMs/60000)}{number('maxAgeMinutes','입력 최대 나이 · 분',c.maxAgeMs/60000)}{c.kind==='AXES'?<>{['x','y'].map(axis=><React.Fragment key={axis}>{text(axis+'.label',axis.toUpperCase()+'축 이름',c[axis].label)}{number(axis+'.center',axis.toUpperCase()+'축 중심',c[axis].center)}{number(axis+'.scale',axis.toUpperCase()+'축 정규화 단위',c[axis].scale)}</React.Fragment>)}{number('highIntensity','강한 국면의 거리',c.highIntensity)}</>:<>{text('question','JEV 질문',c.question)}{c.inputs.map((value,i)=><React.Fragment key={i}>{text('inputs.'+i,'입력 포트 '+(i+1),value)}<button type="button" className="button small nodrag" disabled={data.saving||c.inputs.length<=1} onClick={()=>patch({...c,inputs:c.inputs.filter((_,j)=>j!==i)})}>입력 삭제</button></React.Fragment>)}<button type="button" className="button small nodrag" disabled={data.saving} onClick={()=>{let i=c.inputs.length+1;while(c.inputs.includes('input-'+i))i++;patch({...c,inputs:[...c.inputs,'input-'+i]});}}>입력 추가</button><p className="strategy-inline-caption">판단 선택지는 연결된 선택지 목록에서 읽습니다.</p></>}</>;
 return null;
}
